mapper.select:
UPDATE local_device_pairing_codes
SET consumed_at = #{now}
WHERE code_hash = #{codeHash}
  AND consumed_at IS NULL
  AND expires_at > #{now}
RETURNING id, user_id AS userId, expires_at AS expiresAt, consumed_at AS consumedAt

mapper.insert:
INSERT INTO local_devices (
  id, user_id, name, platform, agent_version, token_hash,
  last_seen_at, created_at, updated_at
) VALUES (
  #{id}, #{userId}, #{name}, #{platform}, #{agentVersion}, #{tokenHash},
  #{now}, #{now}, #{now}
)

mapper.select:
SELECT id, user_id AS userId, revoked_at AS revokedAt
FROM local_devices
WHERE token_hash = #{tokenHash}

mapper.update:
UPDATE local_devices
SET agent_version = #{agentVersion},
    last_seen_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
  AND revoked_at IS NULL
